import React, { createContext, useState } from "react";
import axios from "../utils/Axios";
const APIContext = createContext(null);

export const ApiProvider = ({ children }) => {

    const getGameList = async (provider, page, pageSize, filter = "") => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/get-gamelists`, {
            provider,
            page,
            pageSize,
            filter,
        });
        return res;
    }

    const triggerGame = async (PlayerId, GameId, provider) => {
        // console.log(provider, "provider")
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/createSession`, {
            PlayerId,
            GameId,
            provider
        });
        // const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/create-demo`, {
        //     BankGroupId,
        //     GameId,
        // });
        return res;
    }

    const openDemo = async (BankGroupId, GameId) => {

        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/create-demo`, {
            BankGroupId,
            GameId,
        });
        return res;
    }

    const closeGame = async (SessionId) => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/closeSession`, {
            SessionId
        });
    }

    const login = async (email, password) => {
        const data = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/users/signin`, {
            email,
            password,
        });
        return data;
    };

    const getInfo = async (userId) => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/users/info`, {
            userId,
            update: false
        });
        return res;
    }

    const getProviders = async () => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/get-providers`);
        return res;
    }

    const getJackpot = async () => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/jackpot/getJackpot`);
        return res;
    }

    return (
        <APIContext.Provider
            value={{
                getGameList,
                triggerGame,
                closeGame,
                openDemo,
                login,
                getInfo,
                getProviders,
                getJackpot
            }}
        >
            {children}
        </APIContext.Provider>
    );
};

export default APIContext;